-- supabase/sql/exam_question_bank_neet_pg_set7.sql
--
-- Seventh curated question-bank batch for 'NEET PG' (see exam_patterns_neet_pg.sql for the exam's
-- structure, and Sets 1-6 for the earlier batches -- same table/schema, no migration needed).
-- All-new questions, no overlap with Sets 1 through 6.
--
-- Same format as the earlier sets: every row is format='mcq' with a single isCorrect:true option,
-- matching NEET PG's 100% single-best-response format. 16 chapters (8 Pre-/Para-Clinical
-- Sciences, 4 Clinical Medicine and Allied, 2 Surgery and Allied, 2 Obstetrics/Gynaecology/
-- Anesthesia) each get 4 questions, covering classic, high-yield MBBS/board-style facts.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_neet_pg.sql and
-- exam_question_bank_neet_pg_set1.sql through set6.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- Anatomy
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'medium', 'mcq',
 'Injury to the radial nerve in the spiral (radial) groove of the humerus classically causes:',
 '[{"text":"Wrist drop","isCorrect":true},{"text":"Claw hand","isCorrect":false},{"text":"Foot drop","isCorrect":false},{"text":"Winging of the scapula","isCorrect":false}]'::jsonb,
 null, 'The radial nerve runs in the spiral groove of the humerus and, when injured there, causes wrist drop due to paralysis of the wrist and finger extensors.'),
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'medium', 'mcq',
 'The internal jugular vein primarily drains blood from the:',
 '[{"text":"Lower limbs","isCorrect":false},{"text":"Brain, face, and neck (via the dural venous sinuses)","isCorrect":true},{"text":"Abdominal organs","isCorrect":false},{"text":"Kidneys","isCorrect":false}]'::jsonb,
 null, 'The internal jugular vein drains blood from the dural venous sinuses of the brain, as well as the superficial structures of the face and neck.'),
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'hard', 'mcq',
 'Meckel''s diverticulum is a congenital remnant of which embryological structure?',
 '[{"text":"The urachus","isCorrect":false},{"text":"The vitelline (omphalomesenteric) duct","isCorrect":true},{"text":"The neural tube","isCorrect":false},{"text":"The branchial arches","isCorrect":false}]'::jsonb,
 null, 'Meckel''s diverticulum arises from incomplete obliteration of the vitelline (omphalomesenteric) duct, which normally connects the yolk sac to the midgut in early development.'),
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'medium', 'mcq',
 'Below the inguinal ligament, the femoral artery is a direct continuation of the:',
 '[{"text":"Internal iliac artery","isCorrect":false},{"text":"External iliac artery","isCorrect":true},{"text":"Common iliac artery","isCorrect":false},{"text":"Popliteal artery","isCorrect":false}]'::jsonb,
 null, 'The external iliac artery becomes the femoral artery as it passes beneath the inguinal ligament into the lower limb.'),

